<?php declare(strict_types=1);
if(!$profile||!$inventory->canReadLoans())return;
$profileInventoryMessages=$managerLanguageMessages??[];
$profileInventoryText=static fn(string $source,array $values=[]):string=>\Kulturhus\Native\Language\MemberProfileMessages::text($source,$profileInventoryMessages,$values);
$profilePlaces=$inventory->whereabouts(['member'=>$profile['id']],true);$profileLoans=$inventory->loans('open',$profile['id']);
?>
<section class="card iv-profile"><div class="section-heading"><div><h2><?= e($profileInventoryText('Gegenstände bei dieser Person')) ?></h2><p class="muted"><?= e($profileInventoryText('Hier sehen Sie die aufbewahrten Gegenstände und offenen Ausleihen. Zum Ändern einen Gegenstand oder eine Ausleihe öffnen.')) ?></p></div><?php if($inventory->canWriteLoans()): ?><a class="btn btn-outline theme-secondary button secondary" href="<?= e(url(['view'=>'inventory','tab'=>'loans','new_loan'=>1,'borrower'=>$profile['id']])) ?>"><?= e($profileInventoryText('+ Ausleihe')) ?></a><?php endif ?></div>
<div class="iv-profile-list"><?php foreach($profilePlaces as $p): ?><div><strong><?= e($p['item_name']) ?> · <?= e(\Kulturhus\Verein\Inventory::contentSummary($p,(int)$p['quantity'],$profileInventoryText)?:$p['quantity'].' '.$p['unit']) ?></strong><p><?= e($p['location_name']) ?> · <?= e($p['holder_name']??$profileInventoryText('Ohne Aufbewahrer')) ?></p><small><?= e($p['responsible_id']===$profile['id']?$profileInventoryText('Zuständig · '):'') ?><?= e($profileInventoryText(['available'=>'Verfügbar','reserved'=>'Reserviert','issued'=>'Ausgeliehen','blocked'=>'Gesperrt / Wartung'][$p['state']])) ?></small><?php if($inventory->canRead()): ?><a href="<?= e(url(['view'=>'inventory','tab'=>'items','item'=>$p['item_id']])) ?>"><?= e($profileInventoryText('Gegenstand öffnen →')) ?></a><?php endif ?><?php if($canFinance&&$p['cash_account']): ?><a href="<?= e(url(['view'=>'finance','tab'=>'bank','account'=>$p['cash_account']])) ?>"><?= e($profileInventoryText('Handkasse / Kassenbuch →')) ?></a><?php endif ?></div><?php endforeach;if(!$profilePlaces): ?><p class="muted"><?= e($profileInventoryText('Keine Gegenstände in Aufbewahrung oder Zuständigkeit.')) ?></p><?php endif ?></div>
<h3><?= e($profileInventoryText('Offene Ausleihen')) ?></h3><div class="iv-profile-list"><?php foreach($profileLoans as $l): ?><a href="<?= e(url(['view'=>'inventory','tab'=>'loans','loan'=>$l['id']])) ?>"><strong><?= e(\Kulturhus\Verein\Inventory::number((int)$l['number']).' · '.$l['purpose']) ?></strong><small><?= e($profileInventoryText(\Kulturhus\Verein\Inventory::loanStateLabel($l))) ?> · <?= e(!empty($l['window_end'])?$profileInventoryText('Rückgabe {date} (Berlin)',['date'=>\Kulturhus\Verein\Inventory::windowLocal($l['window_end'],'d.m.Y H:i')]):$profileInventoryText('Rückgabe {date}',['date'=>dateDe($l['due_on'])])) ?></small></a><?php endforeach;if(!$profileLoans): ?><p class="muted"><?= e($profileInventoryText('Keine offenen Ausleihen.')) ?></p><?php endif ?></div><a href="<?= e(url(['view'=>'inventory','tab'=>'loans','borrower'=>$profile['id']])) ?>"><?= e($profileInventoryText('Alle Ausleihen dieses Profils →')) ?></a></section>
